-- F8: internal preparation, externally documented receipts and isolated diligence grants.
-- No connector credential, approved package, external awareness or petition is seeded/executed.
create table public.legal_expansion_audit(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null,case_id uuid,category text not null,event_type text not null,actor_id uuid not null references auth.users(id),metadata jsonb not null default '{}',created_at timestamptz not null default clock_timestamp(),unique(id,case_id,tenant_id),foreign key(case_id,tenant_id) references public.legal_cases(id,tenant_id)
);
create table public.legal_operation_coverage_versions(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),coverage_key text not null,version_number integer not null,previous_version_id uuid,title text not null,provider text not null check(provider in ('domicilio','djen','mni','inss','onr','other')),operation text not null check(operation in ('domicilio_list','domicilio_logs','domicilio_awareness','court_case_read','court_publication_read','petition_submit','inss_request','registry_search','registry_signature','other_manual')),api_version text not null,environment text not null check(environment in ('production','homologation')),institution_reference text not null,court text not null,degree text not null,channel text not null,documentation_url text not null,checked_on date,permission_document_id uuid references public.legal_case_documents(id),permission_document_sha256 text,valid_from date,valid_until date,limitations text not null default '',permission_state text not null check(permission_state in ('unverified','documented','denied')),state text not null default 'draft' check(state in ('draft','reviewed','revoked')),created_by uuid not null references public.profiles(id),created_at timestamptz not null default clock_timestamp(),reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,review_note text not null default '',unique(tenant_id,coverage_key,version_number),check(isfinite(checked_on) and isfinite(valid_from) and isfinite(valid_until)),check(valid_until>=valid_from)
);
create table public.legal_operation_homologations(
 id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id),coverage_version_id uuid not null references public.legal_operation_coverage_versions(id),scenario text not null,result text not null check(result in ('passed','failed','inconclusive')),evidence_document_id uuid not null references public.legal_case_documents(id),evidence_sha256 text not null,tested_on date not null check(isfinite(tested_on)),note text not null,created_by uuid not null references public.profiles(id),created_at timestamptz not null default clock_timestamp()
);
